  [227685] = { "Punta il Modified Shadow Scalpel su Arkonos il Maledetto per dissolvere la sua barriera protettiva.\nCuthbert ha infuso in questo strumento l'ultima benedizione di Rowan. Con un po' di fortuna dovrebbe servire a infrangere la barriera che protegge Arkonos.", 0x4dbd455f, "u" },
  [227687] = { "Dai una... strofinata al dente di Orthas. Che schifo.\nHa un odore terribile.", 0xd64f0701, "u" },
  [227690] = { "Ti si rivolta lo stomaco quando la tua pelle nuda tocca questa pietra runica.", 0xa232d3e5, "u" },
  [227727] = { "Ti insegna a creare un ⟦Sulfuron Hammer=Martello di Sulfuron⟧.", 0x381d3f18, "u" },
